import sys

def main():
    import sys
    input = sys.stdin.read().splitlines()
    t = int(input[0])
    index = 1
    results = []
    for _ in range(t):
        s = input[index]
        c = input[index + 1]
        index += 2
        if len(s) == 1 and s == c:
            results.append('YES')
        elif len(s) > 1:
            if s.count(c) % 2 == 1:
                results.append('YES')
            else:
                results.append('NO')
        else:
            results.append('NO')
    print('\n'.join(results))

main()
